import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Inline CUDA/C++ code implementing naive 3D convolution, channelwise softmax, and 3D max pooling
cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>
#include <cmath>

// -------------------------------------------
// Naive 3D Convolution
// input:  [N, C_in, D, H, W]
// weight: [C_out, C_in, K, K, K]
// bias:   [C_out]
// output: [N, C_out, D_out, H_out, W_out] (valid convolution, no padding)
// -------------------------------------------
__global__ void conv3d_naive_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int D, int H, int W,
    int C_out, int K,
    int D_out, int H_out, int W_out)
{
    // Each thread computes one output element
    // total threads = N * C_out * D_out * H_out * W_out
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= N * C_out * D_out * H_out * W_out) return;

    // Decompose idx
    int w_out_i = idx % W_out;
    int temp = idx / W_out;
    int h_out_i = temp % H_out;
    temp = temp / H_out;
    int d_out_i = temp % D_out;
    temp = temp / D_out;
    int c_out_i = temp % C_out;
    int n_i     = temp / C_out;

    // Compute the starting input index
    int d_in_start = d_out_i;
    int h_in_start = h_out_i;
    int w_in_start = w_out_i;

    float val = 0.0f;
    // Accumulate convolution
    for (int c_in_i = 0; c_in_i < C_in; c_in_i++) {
        for (int kd = 0; kd < K; kd++) {
            for (int kh = 0; kh < K; kh++) {
                for (int kw = 0; kw < K; kw++) {
                    int d_in = d_in_start + kd;
                    int h_in = h_in_start + kh;
                    int w_in = w_in_start + kw;
                    float inp = input[n_i * (C_in*D*H*W)
                                 + c_in_i * (D*H*W)
                                 + d_in * (H*W)
                                 + h_in * (W)
                                 + w_in];
                    float wgt = weight[c_out_i * (C_in*K*K*K)
                                 + c_in_i * (K*K*K)
                                 + kd * (K*K)
                                 + kh * K
                                 + kw];
                    val += inp * wgt;
                }
            }
        }
    }
    // Add bias
    val += bias[c_out_i];
    output[idx] = val;
}

torch::Tensor my_conv3d_cuda(torch::Tensor input,
                             torch::Tensor weight,
                             torch::Tensor bias,
                             int kernel_size)
{
    // Shapes
    int N = input.size(0);
    int C_in = input.size(1);
    int D = input.size(2);
    int H = input.size(3);
    int W = input.size(4);

    int C_out = weight.size(0);
    int K = kernel_size;

    // Compute output dims for valid convolution
    int D_out = D - K + 1;
    int H_out = H - K + 1;
    int W_out = W - K + 1;

    auto options = torch::TensorOptions().dtype(input.dtype()).device(input.device());
    auto out = torch::empty({N, C_out, D_out, H_out, W_out}, options);

    int total = N * C_out * D_out * H_out * W_out;
    int blockSize = 256;
    int gridSize = (total + blockSize - 1) / blockSize;

    conv3d_naive_kernel<<<gridSize, blockSize>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C_in, D, H, W,
        C_out, K,
        D_out, H_out, W_out
    );

    return out;
}

// -------------------------------------------
// Channelwise Softmax
// input:  [N, C, D, H, W]
// output: [N, C, D, H, W]  (softmax on dim=1)
// -------------------------------------------
__global__ void channelwise_softmax_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C, int D, int H, int W)
{
    // We assign a thread to each (N, D, H, W) combination
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= N * D * H * W) return;

    int w_i = idx % W;
    int temp = idx / W;
    int h_i = temp % H;
    temp = temp / H;
    int d_i = temp % D;
    int n_i = temp / D;

    // Find sum of exp
    float maxval = -1e30f;
    for (int c = 0; c < C; c++) {
        float val = input[n_i * (C*D*H*W)
                      + c * (D*H*W)
                      + d_i * (H*W)
                      + h_i * (W)
                      + w_i];
        if (val > maxval) {
            maxval = val;
        }
    }

    float accum = 0.f;
    for (int c = 0; c < C; c++) {
        float val = input[n_i * (C*D*H*W)
                      + c * (D*H*W)
                      + d_i * (H*W)
                      + h_i * (W)
                      + w_i];
        accum += expf(val - maxval);
    }

    // Write normalized exp
    for (int c = 0; c < C; c++) {
        float val = input[n_i * (C*D*H*W)
                      + c * (D*H*W)
                      + d_i * (H*W)
                      + h_i * (W)
                      + w_i];
        output[n_i * (C*D*H*W)
               + c * (D*H*W)
               + d_i * (H*W)
               + h_i * (W)
               + w_i] = expf(val - maxval) / accum;
    }
}

torch::Tensor my_softmax_cuda(torch::Tensor input)
{
    int N = input.size(0);
    int C = input.size(1);
    int D = input.size(2);
    int H = input.size(3);
    int W = input.size(4);

    auto out = torch::zeros_like(input);

    int total = N * D * H * W;
    int blockSize = 256;
    int gridSize = (total + blockSize - 1) / blockSize;

    channelwise_softmax_kernel<<<gridSize, blockSize>>>(
        input.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, D, H, W
    );

    return out;
}

// -------------------------------------------
// Naive 3D MaxPool
// input:  [N, C, D, H, W]
// pool_size: int (kernel along D,H,W equally)
// output: [N, C, D', H', W'] with D' = D/pool_size, etc.
// -------------------------------------------
__global__ void maxpool3d_naive_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C, int D, int H, int W,
    int pool_size,
    int D_out, int H_out, int W_out)
{
    // One thread per output element
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= N * C * D_out * H_out * W_out) return;

    int w_out_i = idx % W_out;
    int temp = idx / W_out;
    int h_out_i = temp % H_out;
    temp = temp / H_out;
    int d_out_i = temp % D_out;
    temp = temp / D_out;
    int c_i = temp % C;
    int n_i = temp / C;

    // region start
    int d_start = d_out_i * pool_size;
    int h_start = h_out_i * pool_size;
    int w_start = w_out_i * pool_size;

    float max_val = -1e30f;
    for (int kd = 0; kd < pool_size; kd++) {
        for (int kh = 0; kh < pool_size; kh++) {
            for (int kw = 0; kw < pool_size; kw++) {
                int d_in = d_start + kd;
                int h_in = h_start + kh;
                int w_in = w_start + kw;
                float val = input[n_i * (C*D*H*W)
                              + c_i * (D*H*W)
                              + d_in * (H*W)
                              + h_in * (W)
                              + w_in];
                if (val > max_val) {
                    max_val = val;
                }
            }
        }
    }
    output[idx] = max_val;
}

torch::Tensor my_maxpool3d_cuda(torch::Tensor input, int pool_size)
{
    int N = input.size(0);
    int C = input.size(1);
    int D = input.size(2);
    int H = input.size(3);
    int W = input.size(4);

    int D_out = D / pool_size;
    int H_out = H / pool_size;
    int W_out = W / pool_size;

    auto options = torch::TensorOptions().dtype(input.dtype()).device(input.device());
    auto out = torch::empty({N, C, D_out, H_out, W_out}, options);

    int total = N * C * D_out * H_out * W_out;
    int blockSize = 256;
    int gridSize = (total + blockSize - 1) / blockSize;

    maxpool3d_naive_kernel<<<gridSize, blockSize>>>(
        input.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, D, H, W,
        pool_size,
        D_out, H_out, W_out
    );
    return out;
}
