class ModelNew(nn.Module):
    """
    Optimized model with custom CUDA kernels for 3D convolution, softmax, and max pooling.
    """
    def __init__(self, in_channels, out_channels, kernel_size, pool_kernel_size):
        super(ModelNew, self).__init__()
        # Instead of nn.Conv3d, store weight/bias as parameters
        self.weight = nn.Parameter(torch.randn(out_channels, in_channels, kernel_size, kernel_size, kernel_size))
        self.bias = nn.Parameter(torch.randn(out_channels))
        self.kernel_size = kernel_size
        self.pool_kernel_size = pool_kernel_size

    def forward(self, x):
        # Use our custom kernels
        x = my_ext.my_conv3d_cuda(x, self.weight, self.bias, self.kernel_size)
        x = my_ext.my_softmax_cuda(x)
        x = my_ext.my_maxpool3d_cuda(x, self.pool_kernel_size)
        x = my_ext.my_maxpool3d_cuda(x, self.pool_kernel_size)
        return x


